---
name: camera
description: Tune or extend JSHack's display-only camera behavior, including follow, zoom, focus effects, cinematic transitions, and camera-related input/FOV handoffs.
---

# Camera

Use this skill for camera motion or presentation work in JSHack. Keep camera
state display-only: gameplay coordinates, targeting, and simulation state stay
in `rules/` and are observed through the WorldView.

## Canonical ownership

- `src/display/camera/controller.js` owns the camera resource, smoothing,
  detached focus, transforms, and screen/world coordinate conversion.
- `src/display/camera/follow.js` owns ordinary entity-follow motion.
- `src/display/camera/utils.js` owns direct jumps and eased camera moves.
- `src/display/camera/zoomPunch.js` owns additive combat/reward zoom pulses.
- `src/main.js` owns camera creation, frame-loop ordering, pointer conversion,
  and the final decision between cinematic motion and player follow.
- `src/display/input/inputLock.js` provides overlapping input locks for camera
  cinematics that must temporarily prevent gameplay input.

## Frame-loop invariant

The frame loop updates camera state before rendering, then obtains the cached
WorldView. Ordinary follow happens after the WorldView is available. A camera
cinematic must take precedence over `followEntity()` while active and must
restore `cam._detached`, target coordinates, scale, and any temporary input/FOV
state when it completes.

## Opening flyovers

Opening flyovers belong in a small display-only director such as
`src/display/camera/openingFlyover.js`. Start them only for the intended fresh
run path; save-game restores and debug/spell-reel modes should not unexpectedly
replay a new-game introduction. Draw the unmasked terrain through the opening
landscape pass so gameplay FOV and exploration memory stay canonical. Use
`setInputLock()` with a unique key while the player cannot act.

The opening projects materialized entrances and quest givers in main and reads
outdoor landmark anchors from the cached overworld plan. Use the entrance label
for a site with a dungeon entrance so the tour titles it once. Check that
anchors are on loaded tiles. Keep the route deterministic and budget time per
leg so more stops do not squeeze the title cards.

The flyover composites one cached landscape image per frame. When changing the
world extent, keep the raster pixel budget independent of the number of tiles.
Test landmark placement with `tests/overworldStructures.test.mjs`.

## Verification

Start with focused pure-camera tests:

```bash
deno test --allow-read tests/cameraController.test.mjs tests/openingFlyover.test.mjs
```

For changes that touch frame-loop wiring or layer boundaries, also run:

```bash
deno task guard:architecture
```

When static tests cannot prove the visual handoff, use the runtime-tools skill
for a bounded seeded run. A successful process exit alone is not proof; verify
that the camera starts detached/zoomed out, reaches the player, and restores
input and FOV state.

// display/camera/openingFlyover.js
// Display-only opening flight from the overworld into the player.

const DEFAULT_DURATION = 8.2;
const MIN_SECONDS_PER_LEG = 1.5;
const NPC_STOP_SPACING = 8;

function clamp01(value) {
  return Math.max(0, Math.min(1, Number(value) || 0));
}

function smoothStep(value) {
  const t = clamp01(value);
  return t * t * (3 - 2 * t);
}

function distanceSquared(a, b) {
  const dx = a.x - b.x;
  const dy = a.y - b.y;
  return dx * dx + dy * dy;
}

function validPosition(pos) {
  return Number.isFinite(Number(pos?.x)) && Number.isFinite(Number(pos?.y));
}

function asPosition(pos) {
  return { x: Number(pos.x), y: Number(pos.y) };
}

function selectWaypoints(view, player) {
  const entities = Array.isArray(view?.entities) ? view.entities : [];
  const preferred = entities.filter((entity) => {
    if (!validPosition(entity?.pos) || Number(entity.id) === Number(view?.player?.id)) return false;
    const tags = Array.isArray(entity.tags) ? entity.tags : [];
    return tags.includes("dungeon_entrance") || tags.includes("landmark") || tags.includes("quest_giver");
  });
  const fallback = entities.filter((entity) => {
    if (!validPosition(entity?.pos) || Number(entity.id) === Number(view?.player?.id)) return false;
    return String(entity.kind || "") !== "default";
  });
  const pool = preferred.length > 0 ? preferred : fallback;
  const selected = [];
  for (const entity of pool) {
    const point = { ...asPosition(entity.pos), title: String(entity.title || "").trim() };
    if (entity.tags?.includes("quest_giver")) {
      const overlaps = selected.some((chosen) => distanceSquared(point, chosen) < NPC_STOP_SPACING ** 2);
      if (overlaps || distanceSquared(point, player) < NPC_STOP_SPACING ** 2) continue;
    }
    selected.push(point);
  }
  return selected;
}

function findFarCorner(player, points, worldBounds) {
  if (worldBounds) {
    const inset = 12;
    const corners = [
      { x: worldBounds.minX + inset, y: worldBounds.minY + inset },
      { x: worldBounds.minX + inset, y: worldBounds.maxY - inset },
      { x: worldBounds.maxX - inset, y: worldBounds.minY + inset },
      { x: worldBounds.maxX - inset, y: worldBounds.maxY - inset },
    ];
    return corners.reduce((best, point) => (
      distanceSquared(point, player) > distanceSquared(best, player) ? point : best
    ));
  }
  const all = [player, ...points];
  const bounds = all.reduce((result, point) => ({
    minX: Math.min(result.minX, point.x),
    maxX: Math.max(result.maxX, point.x),
    minY: Math.min(result.minY, point.y),
    maxY: Math.max(result.maxY, point.y),
  }), { minX: player.x, maxX: player.x, minY: player.y, maxY: player.y });
  const pad = 20;
  const corners = [
    { x: bounds.minX - pad, y: bounds.minY - pad },
    { x: bounds.minX - pad, y: bounds.maxY + pad },
    { x: bounds.maxX + pad, y: bounds.minY - pad },
    { x: bounds.maxX + pad, y: bounds.maxY + pad },
  ];
  return corners.reduce((best, point) => (
    distanceSquared(point, player) > distanceSquared(best, player) ? point : best
  ));
}

function buildRoute(view) {
  const player = validPosition(view?.player?.pos) ? asPosition(view.player.pos) : null;
  if (!player) return null;
  const waypoints = selectWaypoints(view, player);
  const route = [findFarCorner(player, waypoints, view.bounds)];
  while (waypoints.length > 0) {
    const from = route[route.length - 1];
    let nearest = 0;
    for (let i = 1; i < waypoints.length; i++) {
      if (distanceSquared(from, waypoints[i]) < distanceSquared(from, waypoints[nearest])) nearest = i;
    }
    route.push(waypoints.splice(nearest, 1)[0]);
  }
  return [...route, player];
}

function interpolate(a, b, t) {
  return {
    x: a.x + (b.x - a.x) * t,
    y: a.y + (b.y - a.y) * t,
  };
}

/**
 * @param {{ startScale:number, endScale:number, duration?:number, onComplete?:() => void }} opts
 */
export function createOpeningFlyover(opts = {}) {
  const startScale = Math.max(1, Number(opts.startScale) || 1);
  const endScale = Math.max(1, Number(opts.endScale) || startScale);
  let duration = DEFAULT_DURATION;
  let route = null;
  let elapsed = 0;
  let active = false;

  function start(cam, view) {
    if (active) return true;
    route = buildRoute(view);
    if (!route) return false;
    duration = Math.max(1, Number(opts.duration) || Math.max(DEFAULT_DURATION, (route.length - 1) * MIN_SECONDS_PER_LEG));
    elapsed = 0;
    active = true;
    cam._detached = true;
    cam.x = route[0].x;
    cam.y = route[0].y;
    cam.targetX = route[0].x;
    cam.targetY = route[0].y;
    cam.scale = startScale;
    cam.targetScale = startScale;
    return true;
  }

  function update(cam, view, dt) {
    if (!active && !start(cam, view)) return false;
    elapsed += Math.max(0, Number(dt) || 0);
    const progress = clamp01(elapsed / duration);
    const segmentCount = route.length - 1;
    const segmentProgress = progress * segmentCount;
    const segmentIndex = Math.min(segmentCount - 1, Math.floor(segmentProgress));
    const localProgress = segmentProgress - segmentIndex;
    const position = interpolate(route[segmentIndex], route[segmentIndex + 1], smoothStep(localProgress));
    cam.x = position.x;
    cam.y = position.y;
    cam.scale = startScale + (endScale - startScale) * smoothStep(progress);
    cam.targetX = cam.x;
    cam.targetY = cam.y;
    cam.targetScale = cam.scale;

    if (progress < 1) return true;
    const player = validPosition(view?.player?.pos) ? view.player.pos : route[route.length - 1];
    cam.x = cam.targetX = Number(player.x);
    cam.y = cam.targetY = Number(player.y);
    cam.scale = cam.targetScale = endScale;
    cam._detached = false;
    active = false;
    route = null;
    if (typeof opts.onComplete === "function") opts.onComplete();
    return false;
  }

  function getTitleCard() {
    if (!active) return null;
    const segmentSeconds = duration / (route.length - 1);
    const index = Math.round(elapsed / segmentSeconds);
    const title = route[index]?.title;
    if (!title) return null;
    const distance = Math.abs(elapsed - index * segmentSeconds);
    const halfWindow = Math.min(0.9, segmentSeconds * 0.45);
    if (distance >= halfWindow) return null;
    return { title, alpha: smoothStep((halfWindow - distance) / (halfWindow * 0.45)) };
  }

  return { start, update, getTitleCard, isActive: () => active };
}

import { applyCamera } from "./controller.js";

const TILE_PIXELS = 8;
const MAX_LANDSCAPE_PIXELS = 1344;

/**
 * Bake a static overview in strips so setup can yield between batches.
 * Bounds are inclusive tile centers.
 */
export async function bakeOpeningLandscape(surface, bounds, drawStrip, yieldFrame) {
  const { minX, minY, maxX, maxY } = bounds;
  const width = maxX - minX + 1;
  const height = maxY - minY + 1;
  const tilePixels = Math.max(1, Math.min(TILE_PIXELS, Math.floor(MAX_LANDSCAPE_PIXELS / Math.max(width, height))));
  surface.width = width * tilePixels;
  surface.height = height * tilePixels;
  const context = surface.getContext("2d", { alpha: false });
  if (!context) return null;
  context.fillStyle = "#0b0e16";
  context.fillRect(0, 0, surface.width, surface.height);
  context.setTransform(
    tilePixels, 0, 0, tilePixels,
    (0.5 - minX) * tilePixels, (0.5 - minY) * tilePixels,
  );
  const stripHeight = 12;
  for (let y = minY; y <= maxY; y += stripHeight) {
    drawStrip(context, minX, y, maxX, Math.min(maxY, y + stripHeight - 1));
    if (y + stripHeight <= maxY) await yieldFrame();
  }
  return { surface, x: minX - 0.5, y: minY - 0.5, width, height };
}

export function drawOpeningLandscape(ctx, canvas, cam, landscape, alpha = 1) {
  ctx.save();
  if (alpha === 1) {
    ctx.fillStyle = "#0b0e16";
    ctx.fillRect(0, 0, canvas.width, canvas.height);
  }
  ctx.globalAlpha = alpha;
  ctx.imageSmoothingEnabled = true;
  applyCamera(ctx, cam, canvas);
  ctx.drawImage(landscape.surface, landscape.x, landscape.y, landscape.width, landscape.height);
  ctx.restore();
}

export function drawOpeningTitleCard(ctx, width, height, card) {
  if (!card) return;
  const size = Math.max(18, Math.min(42, width * 0.055, height * 0.09));
  const x = width * 0.5;
  const y = height * 0.72;
  ctx.save();
  ctx.globalAlpha = card.alpha;
  ctx.font = `${size}px Georgia, serif`;
  ctx.textAlign = "center";
  ctx.textBaseline = "middle";
  ctx.lineJoin = "round";
  ctx.lineWidth = Math.max(3, size * 0.12);
  ctx.strokeStyle = "#101017";
  ctx.fillStyle = "#fff2d5";
  ctx.strokeText(card.title, x, y, width * 0.86);
  ctx.fillText(card.title, x, y, width * 0.86);
  ctx.restore();
}

import { assert, assertEquals, assertNotEquals } from "jsr:@std/assert";
import { createOpeningFlyover } from "../src/display/camera/openingFlyover.js";

function makeView() {
  return {
    player: { id: 1, pos: { x: 0, y: 0 } },
    entities: [
      { id: 2, kind: "stair_down", pos: { x: 42, y: 18 }, title: "Bear Cave", tags: ["dungeon_entrance"] },
      { id: 3, kind: "quest_giver", pos: { x: -28, y: -20 }, title: "The Miller", tags: ["quest_giver"] },
      { id: 4, kind: "tree", pos: { x: 20, y: -42 }, tags: [] },
    ],
  };
}

Deno.test("opening flyover starts far away and reaches the player", () => {
  let completed = false;
  const cam = { x: 0, y: 0, scale: 70, targetX: 0, targetY: 0, targetScale: 70 };
  const flyover = createOpeningFlyover({
    startScale: 28,
